import 'package:flutter/material.dart';import 'package:intl/intl.dart';import '../models/finance_models.dart';import '../services/database_service.dart';import '../services/finance_calculator.dart';import '../widgets/brand_header.dart';import '../widgets/finance_ui.dart';
class DashboardScreen extends StatefulWidget{const DashboardScreen({super.key});@override State<DashboardScreen> createState()=>_DashboardScreenState();}
class _DashboardScreenState extends State<DashboardScreen>{
 DateTime anchor=DateTime.now();bool loading=true;List<IncomeEntry> income=[];List<ExpenseRecord> expenses=[];List<PayrollPayment> payroll=[];List<StockCost> costs=[];
 @override void initState(){super.initState();load();}
 Future<void> load()async{setState(()=>loading=true);final s=DateTime(anchor.year,anchor.month,1),e=DateTime(anchor.year,anchor.month+1,1);final v=await Future.wait([DatabaseService.instance.income(start:s,end:e),DatabaseService.instance.expenses(start:s,end:e),DatabaseService.instance.payroll(start:s,end:e),DatabaseService.instance.stockCosts()]);if(!mounted)return;setState(()=>{income=v[0] as List<IncomeEntry>,expenses=v[1] as List<ExpenseRecord>,payroll=v[2] as List<PayrollPayment>,costs=(v[3] as List<StockCost>).where((x)=>!x.date.isBefore(s)&&x.date.isBefore(e)).toList(),loading=false});}
 @override Widget build(BuildContext c){final x=FinanceCalculator.summarize(income:income,expenses:expenses,payroll:payroll,stockCosts:costs);return Scaffold(appBar:AppBar(title:const BrandHeader(),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[Text('Finance overview',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const Text('Business performance and cost monitoring',style:TextStyle(color:Colors.blueGrey)),Card(child:Row(children:[IconButton(onPressed:(){setState(()=>anchor=DateTime(anchor.year,anchor.month-1,1));load();},icon:const Icon(Icons.chevron_left)),Expanded(child:Text(DateFormat('MMMM yyyy').format(anchor),textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.w700))),IconButton(onPressed:(){setState(()=>anchor=DateTime(anchor.year,anchor.month+1,1));load();},icon:const Icon(Icons.chevron_right))])),const SizedBox(height:12),Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:x.operatingResult>=0?const Color(0xFF0D766D):const Color(0xFF9A3F37),borderRadius:BorderRadius.circular(20)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Net operating result',style:TextStyle(color:Colors.white70)),const SizedBox(height:8),Text(FinanceCalculator.money(x.operatingResult),style:const TextStyle(color:Colors.white,fontSize:29,fontWeight:FontWeight.w800))])),const SizedBox(height:12),GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:2,childAspectRatio:1.55,crossAxisSpacing:10,mainAxisSpacing:10,children:[_metric('Income',x.income,Icons.south_west,Colors.teal),_metric('Expenses',x.expenses,Icons.receipt_long,Colors.deepOrange),_metric('Payroll',x.payroll,Icons.groups,Colors.indigo),_metric('COGS adjustments',x.cogs,Icons.inventory_2,Colors.blueGrey)]),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Period breakdown',style:TextStyle(fontWeight:FontWeight.w700)),FinanceUi.row('Income',x.income),FinanceUi.row('Expenses',-x.expenses),FinanceUi.row('Payroll',-x.payroll),FinanceUi.row('COGS adjustments',-x.cogs),const Divider(),FinanceUi.row('Net result',x.operatingResult,bold:true)]))),const Card(child:Padding(padding:EdgeInsets.all(14),child:Text('Income is entered separately and is not synced from Billit sales. COGS is based on entered stock-cost adjustments, not a perpetual-inventory valuation.'))),FilledButton.icon(onPressed:()=>incomeDialog(c),icon:const Icon(Icons.add),label:const Text('Record income'))])));}
 Widget _metric(String t,double v,IconData i,Color col)=>Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Icon(i,color:col),Text(FinanceCalculator.money(v),style:const TextStyle(fontSize:17,fontWeight:FontWeight.w800)),Text(t,style:const TextStyle(color:Colors.blueGrey))])));
 Future<void> incomeDialog(BuildContext c)async{final src=TextEditingController(text:'Sales'),amt=TextEditingController(),note=TextEditingController();final ok=await showDialog<bool>(context:c,builder:(d)=>AlertDialog(title:const Text('Record income'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:src,decoration:const InputDecoration(labelText:'Source')),FinanceUi.amountField(amt),TextField(controller:note,decoration:const InputDecoration(labelText:'Note'))]),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Save'))]));final a=double.tryParse(amt.text);if(ok==true&&a!=null&&a>0){await DatabaseService.instance.addIncome(IncomeEntry(id:null,date:DateTime.now(),source:src.text,amount:a,note:note.text));await load();}src.dispose();amt.dispose();note.dispose();}
}
